preConditionHook:
// All-of-N, written as ConsecutiveUpBars writes it: start true and let any
// failing pair clear the flag, which is the EL twin's shape as well. A pair
// that only ties (high[ii] == high[ii + 1] within the EL tolerance) FAILS both
// sides, since 'trending highs and lows' means strictly higher on both the
// highs and the lows.
upTrend = true;
downTrend = true;
for (ii = 0; ii < (int)trendBars; ++ii) {
    if (el_le(high[ii], high[ii + 1]) || el_le(low[ii], low[ii + 1])) upTrend = false;
    if (el_ge(high[ii], high[ii + 1]) || el_ge(low[ii], low[ii + 1])) downTrend = false;
}
